using System;using System.IO;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEngine.AI;using RoadGunner;
public static class WastelandExtraChecks {
 static GameSession s;static async Task Wait(float secs){float end=Time.realtimeSinceStartup+secs;while(Time.realtimeSinceStartup<end)await Task.Delay(25);}
 public static async Task<string> Main(){s=UnityEngine.Object.FindAnyObjectByType<GameSession>();var l=UnityEngine.Object.FindAnyObjectByType<LevelLayout>();string result="";int oldFps=Application.targetFrameRate;var oldVsync=QualitySettings.vSyncCount;try{s.Restart();s.spawns.enabled=false;s.turret.enabled=false;s.health.DamageEnabled=false;foreach(var e in s.spawns.pool)e.Despawn();foreach(var b in s.spawns.buggyPool)b.Despawn();s.input.testInput=true;s.input.testBrake=true;s.input.testDirection=Vector2.zero;s.vehicle.Body.constraints=RigidbodyConstraints.FreezeAll;
 var wreck=l.decorationRoot.Find("H · Travel landmarks and shoulder salvage").Cast<Transform>().First(t=>t.name.Contains("Abandoned pickup"));var start=wreck.TransformPoint(new Vector3(-4,0,0));var end=wreck.TransformPoint(new Vector3(4,.7f,0));s.vehicle.ResetPose(end,Quaternion.Euler(0,45,0));var r=s.spawns.authoredRaiders[0];r.enabled=true;NavMesh.SamplePosition(start,out var hit,3,NavMesh.AllAreas);r.Spawn(hit.position,-1,2);float initial=Vector3.Distance(r.transform.position,end),maxDeviation=0;bool animated=false;int maxCorners=0;for(int i=0;i<220;i++){await Wait(.04f);maxDeviation=Mathf.Max(maxDeviation,Mathf.Abs(wreck.InverseTransformPoint(r.transform.position).z));maxCorners=Math.Max(maxCorners,r.agent.path.corners.Length);animated|=Quaternion.Angle(r.leftLeg.localRotation,Quaternion.identity)>3;if(Vector3.Distance(r.transform.position,end)<3.8f)break;}float final=Vector3.Distance(r.transform.position,end);bool pass=final<initial-3&&maxDeviation>2&&animated&&r.agent.isOnNavMesh;result+=(pass?"PASS ":"FAIL ")+"raider navigates around vehicle wreck, animated: distance="+initial.ToString("F2")+" -> "+final.ToString("F2")+", detour="+maxDeviation.ToString("F2")+", path corners="+maxCorners+", animated="+animated+"\n";r.Despawn();
 var workshop=UnityEngine.Object.FindAnyObjectByType<RepairWorkshop>();s.vehicle.ResetPose(workshop.transform.position+Vector3.up*.7f,Quaternion.identity);s.health.DamageEnabled=true;QualitySettings.vSyncCount=0;foreach(int fps in new[]{30,60}){Application.targetFrameRate=fps;s.health.ResetHealth();s.health.Damage(80,false);await Wait(.2f);float hp=s.health.Current,time=Time.time;int frame=Time.frameCount;await Wait(1.6f);float elapsed=Time.time-time;float actual=s.health.Current-hp,expected=10*elapsed;result+=(Mathf.Abs(actual-expected)<1?("PASS "):("FAIL "))+"repair frame-rate check target="+fps+", measured="+((Time.frameCount-frame)/elapsed).ToString("F1")+" FPS, healed="+actual.ToString("F3")+", expected="+expected.ToString("F3")+"\n";}
 }finally{Application.targetFrameRate=oldFps;QualitySettings.vSyncCount=oldVsync;s.vehicle.Body.constraints=RigidbodyConstraints.None;s.spawns.enabled=true;s.turret.enabled=true;s.Restart();}File.WriteAllText("Documentation/RoadGunner/Wasteland-Restore-2026-10-10/ExtraPlayChecks.txt",result);return result;}
}
